    for i in range(n):
        x, y = carpets[i][0], carpets[i][1]
        width, height = carpets[i][2], carpets[i][3]
        if point[0] >= x and point[0] < x + width and point[1] >= y and point[1] < y + height:
            if topmost_carpet == -1:
                topmost_carpet = i
            elif carpets[topmost_carpet][3] < carpets[i][3]:
                topmost_carpet = i
    return topmost_carpet

