def max_value_on_paths(N, grid_values):
    # Create a 2D array to store the maximum values for each cell
    max_values = [[0] * N for _ in range(N)]

    # Loop through the grid values and update the maximum values for each cell
    for x, y, value in grid_values:
        max_values[y][x] = max(max_values[y][x], value)

    # Initialize the maximum sum of values for the two paths
    max_sum = 0

    # Loop through the grid from the top-left to the bottom-right
    for y in range(N):
        for x in range(N):
            # If the current cell has the maximum value, add the value to the maximum sum
            if max_values[y][x] == value:
                max_sum += value

    return max_sum

