def sum_of_factorials_optimized(n: int) -> int:
    if n < 1 or n > 50:
        raise ValueError("The value of n must be in the range of 1 to 50, inclusive.")

    factorials = [1] * (n + 1)
    for i in range(1, n + 1):
        factorials[i] = i * factorials[i - 1]

    return sum(factorials)

