def verify_isbn(isbn: str) -> str:

    # Check if the input is a valid ISBN number
    if not isbn.isdigit() or len(isbn) != 10:
        return "Invalid ISBN number"

    # Calculate the checksum modulo 11
    checksum = 0
    for i, digit in enumerate(isbn):
        if i % 2 == 0:
            checksum += int(digit)
        else:
            checksum += int(digit) * 3
    checksum %= 11

    # If the checksum is 10, it is converted to 'X'
    if checksum == 10:
        checksum = 'X'

    # If the checksum is different from the last digit of the input, return the corrected ISBN number
    if checksum != isbn[-1]:
        return isbn[:-1] + checksum
    else:
        return "Right"

