    aisle_separation = [[0 for _ in range(N)] for _ in range(M)]

    # Iterate over the chatting pairs and update the matrix
    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        for i in range(M):
            for j in range(N):
                if i <= Xi <= i + K and j <= Yi <= j + L:
                    aisle_separation[i][j] += 1

    # Initialize two variables to store the optimal row and column indices for the aisles
    optimal_row = 0
    optimal_col = 0

    # Iterate over the matrix and find the position with the maximum number of chatting pairs that can be separated
    for i in range(M):
        for j in range(N):
            if aisle_separation[i][j] == max(aisle_separation):
                optimal_row = i
                optimal_col = j

    # Return the optimal row and column indices as a space-separated string
    return f'{optimal_row} {optimal_col}'

